-- Local-only PostgreSQL 17 schema. Applied transactionally by the verifier.
CREATE SCHEMA mawid_core;
REVOKE ALL ON SCHEMA mawid_core FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA mawid_core REVOKE ALL ON TABLES FROM PUBLIC;
CREATE TABLE mawid_core.organizations (workspace_id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), configuration_version bigint NOT NULL DEFAULT 1 CHECK(configuration_version>0));
CREATE TABLE mawid_core.locations (workspace_id uuid NOT NULL REFERENCES mawid_core.organizations, location_id uuid NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Beirut', PRIMARY KEY(workspace_id,location_id));
CREATE TABLE mawid_core.principals (database_user name PRIMARY KEY, actor_id uuid NOT NULL UNIQUE);
CREATE TABLE mawid_core.memberships (workspace_id uuid NOT NULL REFERENCES mawid_core.organizations, membership_id uuid NOT NULL DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, location_id uuid, roles text[] NOT NULL CHECK(cardinality(roles)>0 AND roles <@ ARRAY['admin','manager','professional']), revoked_at timestamptz, PRIMARY KEY(workspace_id,membership_id), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE INDEX memberships_actor ON mawid_core.memberships(actor_id,workspace_id,location_id);
CREATE TABLE mawid_core.customer_profiles (workspace_id uuid NOT NULL REFERENCES mawid_core.organizations, customer_id uuid NOT NULL DEFAULT gen_random_uuid(), external_key text NOT NULL CHECK(length(external_key) BETWEEN 1 AND 120), actor_id uuid, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120), contact text CHECK(length(contact)<=200), anonymized_at timestamptz, PRIMARY KEY(workspace_id,customer_id), UNIQUE(workspace_id,external_key));
CREATE UNIQUE INDEX customers_subject ON mawid_core.customer_profiles(workspace_id,actor_id) WHERE actor_id IS NOT NULL;
CREATE TABLE mawid_core.professionals (workspace_id uuid NOT NULL, location_id uuid NOT NULL, professional_id uuid NOT NULL DEFAULT gen_random_uuid(), external_key text NOT NULL, display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 120), active boolean NOT NULL DEFAULT true, PRIMARY KEY(workspace_id,location_id,professional_id), UNIQUE(workspace_id,location_id,external_key), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE TABLE mawid_core.services (workspace_id uuid NOT NULL, location_id uuid NOT NULL, service_id uuid NOT NULL DEFAULT gen_random_uuid(), external_key text NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 1 AND 1440), buffer_before integer NOT NULL DEFAULT 0 CHECK(buffer_before BETWEEN 0 AND 1440), buffer_after integer NOT NULL DEFAULT 0 CHECK(buffer_after BETWEEN 0 AND 1440), PRIMARY KEY(workspace_id,location_id,service_id), UNIQUE(workspace_id,location_id,external_key), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE TABLE mawid_core.eligibility (workspace_id uuid NOT NULL, location_id uuid NOT NULL, professional_id uuid NOT NULL, service_id uuid NOT NULL, PRIMARY KEY(workspace_id,location_id,professional_id,service_id), FOREIGN KEY(workspace_id,location_id,professional_id) REFERENCES mawid_core.professionals, FOREIGN KEY(workspace_id,location_id,service_id) REFERENCES mawid_core.services);
CREATE INDEX eligibility_service ON mawid_core.eligibility(workspace_id,location_id,service_id);
CREATE TABLE mawid_core.opening_intervals (workspace_id uuid NOT NULL, location_id uuid NOT NULL, opening_id uuid NOT NULL DEFAULT gen_random_uuid(), external_key text NOT NULL, weekday integer NOT NULL CHECK(weekday BETWEEN 0 AND 6), opens time NOT NULL, closes time NOT NULL CHECK(closes>opens), PRIMARY KEY(workspace_id,location_id,opening_id), UNIQUE(workspace_id,location_id,external_key), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE TABLE mawid_core.schedule_exceptions (workspace_id uuid NOT NULL, location_id uuid NOT NULL, exception_id uuid NOT NULL DEFAULT gen_random_uuid(), local_date date NOT NULL, opens time, closes time, CHECK((opens IS NULL AND closes IS NULL) OR (opens IS NOT NULL AND closes IS NOT NULL AND closes>opens)), PRIMARY KEY(workspace_id,location_id,exception_id), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE INDEX exceptions_day ON mawid_core.schedule_exceptions(workspace_id,location_id,local_date);
CREATE TABLE mawid_core.professional_intervals (workspace_id uuid NOT NULL, location_id uuid NOT NULL, professional_id uuid NOT NULL, interval_id uuid NOT NULL DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('availability','break','absence')), period tstzrange NOT NULL CHECK(NOT isempty(period) AND NOT lower_inf(period) AND NOT upper_inf(period) AND isfinite(lower(period)) AND isfinite(upper(period)) AND lower_inc(period) AND NOT upper_inc(period)), schedule_version bigint NOT NULL DEFAULT 1 CHECK(schedule_version>0), PRIMARY KEY(workspace_id,location_id,interval_id), FOREIGN KEY(workspace_id,location_id,professional_id) REFERENCES mawid_core.professionals);
CREATE INDEX professional_intervals_lookup ON mawid_core.professional_intervals(workspace_id,location_id,professional_id);
CREATE TABLE mawid_core.bookings (workspace_id uuid NOT NULL, location_id uuid NOT NULL, booking_id uuid NOT NULL DEFAULT gen_random_uuid(), customer_id uuid NOT NULL, service_id uuid NOT NULL, requested_professional_id uuid, assigned_professional_id uuid, requested_start timestamptz NOT NULL, requested_end timestamptz NOT NULL CHECK(requested_end>requested_start AND isfinite(requested_start) AND isfinite(requested_end)), assigned_start timestamptz, assigned_end timestamptz, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','proposed','confirmed','declined','withdrawn','expired','cancelled')), version bigint NOT NULL DEFAULT 1 CHECK(version>0), submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(), response_due_at timestamptz, offer_expires_at timestamptz, cancelled_at timestamptz, cancellation_actor text CHECK(cancellation_actor IN ('customer','salon')), CHECK((assigned_start IS NULL AND assigned_end IS NULL) OR (assigned_start IS NOT NULL AND assigned_end IS NOT NULL AND assigned_end>assigned_start)), CHECK(state NOT IN ('confirmed','proposed') OR (assigned_professional_id IS NOT NULL AND assigned_start IS NOT NULL AND assigned_end IS NOT NULL)), CHECK(state<>'proposed' OR (offer_expires_at IS NOT NULL AND offer_expires_at<=assigned_start)), CHECK(state<>'cancelled' OR (cancelled_at IS NOT NULL AND cancellation_actor IS NOT NULL)), PRIMARY KEY(workspace_id,location_id,booking_id), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations, FOREIGN KEY(workspace_id,customer_id) REFERENCES mawid_core.customer_profiles, FOREIGN KEY(workspace_id,location_id,service_id) REFERENCES mawid_core.services, FOREIGN KEY(workspace_id,location_id,requested_professional_id) REFERENCES mawid_core.professionals, FOREIGN KEY(workspace_id,location_id,assigned_professional_id) REFERENCES mawid_core.professionals);
CREATE INDEX bookings_customer ON mawid_core.bookings(workspace_id,customer_id,requested_start,booking_id);
CREATE INDEX bookings_schedule ON mawid_core.bookings(workspace_id,location_id,requested_start,booking_id);
CREATE INDEX bookings_requested_professional ON mawid_core.bookings(workspace_id,location_id,requested_professional_id);
CREATE INDEX bookings_assigned_professional ON mawid_core.bookings(workspace_id,location_id,assigned_professional_id);
CREATE INDEX bookings_service ON mawid_core.bookings(workspace_id,location_id,service_id);
-- btree_gist must already exist in this disposable local database. No extension enablement here.
CREATE TABLE mawid_core.allocations (workspace_id uuid NOT NULL, location_id uuid NOT NULL, allocation_id uuid NOT NULL DEFAULT gen_random_uuid(), booking_id uuid NOT NULL, professional_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('confirmed','offer')), period tstzrange NOT NULL CHECK(NOT isempty(period) AND NOT lower_inf(period) AND NOT upper_inf(period) AND isfinite(lower(period)) AND isfinite(upper(period)) AND lower_inc(period) AND NOT upper_inc(period)), expires_at timestamptz, CHECK((kind='offer' AND expires_at IS NOT NULL) OR (kind='confirmed' AND expires_at IS NULL)), PRIMARY KEY(workspace_id,location_id,allocation_id), UNIQUE(workspace_id,location_id,booking_id), FOREIGN KEY(workspace_id,location_id,booking_id) REFERENCES mawid_core.bookings, FOREIGN KEY(workspace_id,location_id,professional_id) REFERENCES mawid_core.professionals, EXCLUDE USING gist(workspace_id WITH =, professional_id WITH =, period WITH &&));
CREATE INDEX allocations_professional ON mawid_core.allocations(workspace_id,location_id,professional_id);
CREATE TABLE mawid_core.booking_events (workspace_id uuid NOT NULL, location_id uuid NOT NULL, event_id uuid NOT NULL DEFAULT gen_random_uuid(), booking_id uuid NOT NULL, version bigint NOT NULL CHECK(version>0), actor_id uuid NOT NULL, action text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(workspace_id,event_id), UNIQUE(workspace_id,location_id,booking_id,version), FOREIGN KEY(workspace_id,location_id,booking_id) REFERENCES mawid_core.bookings);
CREATE TABLE mawid_core.outbox (workspace_id uuid NOT NULL, event_id uuid NOT NULL, deliver_after timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered','failed')), safe_error_code text, PRIMARY KEY(workspace_id,event_id), FOREIGN KEY(workspace_id,event_id) REFERENCES mawid_core.booking_events);
CREATE INDEX outbox_delivery ON mawid_core.outbox(status,deliver_after);
CREATE TABLE mawid_core.operation_references (workspace_id uuid NOT NULL, actor_id uuid NOT NULL, operation_id uuid NOT NULL, operation text NOT NULL, input_hash text NOT NULL CHECK(input_hash ~ '^[a-f0-9]{64}$'), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(workspace_id,actor_id,operation_id), FOREIGN KEY(workspace_id) REFERENCES mawid_core.organizations);
CREATE TABLE mawid_core.idempotency_records (workspace_id uuid NOT NULL, actor_id uuid NOT NULL, operation_id uuid NOT NULL, outcome jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(workspace_id,actor_id,operation_id), FOREIGN KEY(workspace_id,actor_id,operation_id) REFERENCES mawid_core.operation_references);
CREATE TABLE mawid_core.import_jobs (workspace_id uuid NOT NULL, location_id uuid NOT NULL, job_id uuid NOT NULL DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('customers','professionals','services','openings')), file_hash text NOT NULL CHECK(file_hash ~ '^[a-f0-9]{64}$'), payload_hash text NOT NULL CHECK(payload_hash ~ '^[a-f0-9]{64}$'), configuration_version bigint NOT NULL, staged_rows jsonb, row_count integer NOT NULL CHECK(row_count BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'previewed' CHECK(status IN ('previewed','committed','expired')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '24 hours', PRIMARY KEY(workspace_id,job_id), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations);
CREATE INDEX import_jobs_expiry ON mawid_core.import_jobs(expires_at) WHERE staged_rows IS NOT NULL;
CREATE TABLE mawid_core.export_jobs (workspace_id uuid NOT NULL, location_id uuid, job_id uuid NOT NULL DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, customer_id uuid, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '15 minutes', PRIMARY KEY(workspace_id,job_id), FOREIGN KEY(workspace_id,location_id) REFERENCES mawid_core.locations, FOREIGN KEY(workspace_id,customer_id) REFERENCES mawid_core.customer_profiles);
CREATE INDEX export_jobs_customer ON mawid_core.export_jobs(workspace_id,customer_id);
CREATE TABLE mawid_core.transfer_audit (workspace_id uuid NOT NULL, audit_id uuid NOT NULL DEFAULT gen_random_uuid(), job_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL, row_count integer NOT NULL CHECK(row_count>=0), occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(workspace_id,audit_id), FOREIGN KEY(workspace_id) REFERENCES mawid_core.organizations);
CREATE TABLE mawid_core.deletion_ledger (workspace_id uuid NOT NULL, customer_id uuid NOT NULL, erased_at timestamptz NOT NULL DEFAULT clock_timestamp(), action text NOT NULL DEFAULT 'anonymize', PRIMARY KEY(workspace_id,customer_id), FOREIGN KEY(workspace_id) REFERENCES mawid_core.organizations);

REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA mawid_core FROM PUBLIC;
